(function(api){
var drops=[], flash=0, nextFlash=0;
function num(k,d){ var p=api.params||{}; return p[k]!=null?+p[k]:d; }
function frame(dt){
  var W=api.width,H=api.height; if(!W||!H) return;
  var f=dt/16.6;
  var ctx=api.ctx;
  ctx.clearRect(0,0,W,H);
  var amt=num('rain',6), wind=num('wind',6), light=num('lightning',2);
  if(amt>0){
    var n=Math.floor(amt*14);
    while(drops.length<n){ drops.push({x:api.rand(0,W+60), y:api.rand(-40,H), l:api.rand(14,30), v:api.rand(8,16)}); }
    if(drops.length>n+30) drops.length=n+30;
    ctx.strokeStyle='rgba(235,235,240,0.4)';
    ctx.lineWidth=1;
    ctx.beginPath();
    for(var i=0;i<drops.length;i++){
      var d=drops[i];
      d.y+=d.v*f*1.6; d.x+=wind*0.35*f*0.6;
      if(d.y>H+30){ d.y=api.rand(-30,0); d.x=api.rand(0,W+60); }
      if(d.x>W+60){ d.x=-30; }
      ctx.moveTo(d.x-(wind*0.8), d.y-d.l);
      ctx.lineTo(d.x,d.y);
    }
    ctx.stroke();
  }
  if(light>0){
    var now=api.now();
    if(now>=nextFlash){
      flash=1;
      nextFlash=now+api.rand(1800,7000)*(10/Math.max(0.5,light));
    }
    if(flash>0.02){
      ctx.fillStyle='rgba(255,255,255,'+(flash*0.55).toFixed(3)+')';
      ctx.fillRect(0,0,W,H);
      flash*=0.88;
    }
  }
}
function clear(){ try{ api.ctx.clearRect(0,0,api.width,api.height); }catch(e){} drops=[]; }
return { frame:frame, clear:clear, resize:clear };
})
